//! Settings → About: the third-party licence notices that ship with the app.
//!
//! `THIRD_PARTY_NOTICES.md` (repo root, generated by `npm run notices`) is bundled as a
//! resource next to the models (tauri.conf.json) and read from there, so Settings shows
//! the same file the installer carries.

use std::path::Path;

use tauri::{AppHandle, Manager};

use super::{CommandError, Result};

/// The notices file's name, in the repo root and in the app's resource folder.
pub const NOTICES_FILE: &str = "THIRD_PARTY_NOTICES.md";

/// The notices file in `resource_dir`.
pub fn read_notices(resource_dir: &Path) -> std::io::Result<String> {
    std::fs::read_to_string(resource_dir.join(NOTICES_FILE))
}

/// The third-party licence notices, as Markdown text.
#[tauri::command(async)]
pub fn third_party_notices(app: AppHandle) -> Result<String> {
    let dir = app.path().resource_dir().map_err(|e| CommandError::Notices(e.to_string()))?;
    read_notices(&dir).map_err(|e| CommandError::Notices(e.to_string()))
}

#[cfg(test)]
mod tests {
    use super::*;

    const NOTICES: &str = include_str!("../../../THIRD_PARTY_NOTICES.md");
    const LOCK: &str = include_str!("../../Cargo.lock");

    #[test]
    fn reads_the_notices_from_the_resource_folder() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join(NOTICES_FILE), "# Notices\n").unwrap();
        assert_eq!(read_notices(dir.path()).unwrap(), "# Notices\n");
    }

    #[test]
    fn a_missing_notices_file_is_an_error() {
        let dir = tempfile::tempdir().unwrap();
        assert!(read_notices(dir.path()).is_err());
    }

    /// The resource map in a Tauri config, as (source, target) pairs.
    fn resources(config: &str) -> Vec<(String, String)> {
        let json: serde_json::Value = serde_json::from_str(config).unwrap();
        let map = json["bundle"]["resources"].as_object().expect("resources is a map");
        map.iter().map(|(k, v)| (k.clone(), v.as_str().unwrap().to_owned())).collect()
    }

    /// The installer carries the file, under the name `third_party_notices` reads, on every
    /// platform (the Windows config has its own resource map, so it names the file too).
    #[test]
    fn the_notices_ship_as_a_resource() {
        let entry = (format!("../{NOTICES_FILE}"), NOTICES_FILE.to_owned());
        for (name, config) in [
            ("tauri.conf.json", include_str!("../../tauri.conf.json")),
            ("tauri.windows.conf.json", include_str!("../../tauri.windows.conf.json")),
        ] {
            assert!(resources(config).contains(&entry), "{name} does not bundle {NOTICES_FILE}");
        }
    }

    /// The locked version of a crate in Cargo.lock.
    fn locked(name: &str) -> String {
        let at = LOCK.find(&format!("name = \"{name}\"\nversion = \"")).unwrap_or_else(|| panic!("{name} not in Cargo.lock"));
        let rest = &LOCK[at..];
        rest.lines().nth(1).unwrap().trim_start_matches("version = \"").trim_end_matches('"').to_owned()
    }

    /// The hand-written section names the versions it was checked against: bumping one of
    /// these crates without running `npm run notices` again fails here.
    #[test]
    fn the_notices_match_the_locked_native_libraries() {
        for name in ["libsqlite3-sys", "openssl-src", "ort-sys", "onig_sys", "webview2-com-sys"] {
            let version = locked(name);
            assert!(NOTICES.contains(&format!("{name} {version}")), "regenerate the notices: {name} is {version} now");
        }
    }

    #[test]
    fn the_notices_cover_the_native_components() {
        for component in [
            "SQLCipher",
            "SQLite",
            "OpenSSL",
            "ONNX Runtime",
            "DirectML",
            "WebView2",
            "Oniguruma",
            "IBM Plex Sans",
            "IBM Plex Mono",
            "Source Serif 4",
            "bge-small-en-v1.5",
        ] {
            assert!(NOTICES.contains(component), "{component} is missing from {NOTICES_FILE}");
        }
    }
}
